import React, { useState, useEffect } from "react"
import { Helmet } from "react-helmet"
import Header from "./header"

const Layout = ({ children, activeSection, setActiveSection, sections }) => {
  const [darkMode, setDarkMode] = useState(false)
  const [isLoading, setIsLoading] = useState(true)
  const [isMobile, setIsMobile] = useState(false)

  // Check for saved theme preference or default to light mode
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const savedTheme = localStorage.getItem('darkMode')
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches
      
      setDarkMode(savedTheme ? JSON.parse(savedTheme) : prefersDark)
      setIsLoading(false)

      // Check mobile
      const checkMobile = () => setIsMobile(window.innerWidth < 768)
      checkMobile()
      window.addEventListener('resize', checkMobile)
      return () => window.removeEventListener('resize', checkMobile)
    }
  }, [])

  // Save theme preference
  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('darkMode', JSON.stringify(darkMode))
      document.documentElement.classList.toggle('dark', darkMode)
    }
  }, [darkMode])

  const toggleDarkMode = () => setDarkMode(!darkMode)

  // Portfolio section needs scrolling, others don't
  const needsScrolling = activeSection === 'portfolio' || activeSection === 'writing'
  
  // Theme colors
  const theme = {
    light: {
      bg: '#fafafa',
      surface: '#ffffff',
      text: '#1f2937',
      textSecondary: '#6b7280',
      border: '#e5e7eb'
    },
    dark: {
      bg: '#0f172a',
      surface: '#1e293b',
      text: '#f8fafc',
      textSecondary: '#cbd5e1',
      border: '#334155'
    }
  }

  const currentTheme = darkMode ? theme.dark : theme.light

  if (isLoading) {
    return (
      <div style={{
        height: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: currentTheme.bg,
        color: currentTheme.text
      }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{
            width: '40px',
            height: '40px',
            border: `3px solid ${currentTheme.border}`,
            borderTop: `3px solid ${currentTheme.text}`,
            borderRadius: '50%',
            animation: 'spin 1s linear infinite',
            margin: '0 auto 1rem'
          }} />
          <p>Loading...</p>
        </div>
      </div>
    )
  }

  return (
    <>
      <Helmet>
        <html lang="en" className={darkMode ? 'dark' : ''} />
        <title>Kartik Bhargava - Tech Blog</title>
        <meta name="description" content="Technology, programming, and development insights" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <meta name="theme-color" content={darkMode ? '#0f172a' : '#ffffff'} />
        
        {/* Open Graph */}
        <meta property="og:title" content="Kartik Bhargava - Tech Blog" />
        <meta property="og:description" content="Technology, programming, and development insights" />
        <meta property="og:type" content="website" />
        <meta property="og:url" content="https://kartikbhargava.github.io" />
        
        {/* Twitter */}
        <meta name="twitter:card" content="summary_large_image" />
        <meta name="twitter:title" content="Kartik Bhargava - Tech Blog" />
        <meta name="twitter:description" content="Technology, programming, and development insights" />
      </Helmet>

      <div style={{ 
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', Roboto, sans-serif",
        height: "100vh",
        background: currentTheme.bg,
        color: currentTheme.text,
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        transition: 'background-color 0.3s ease, color 0.3s ease'
      }}>
        
        <Header 
          activeSection={activeSection} 
          setActiveSection={setActiveSection} 
          sections={sections}
          darkMode={darkMode}
          toggleDarkMode={toggleDarkMode}
          theme={currentTheme}
          isMobile={isMobile}
        />
        
        <main style={{
          flex: 1,
          background: currentTheme.bg,
          overflow: needsScrolling ? "auto" : "hidden",
          display: needsScrolling ? "block" : "flex",
          position: 'relative'
        }}>
          {/* Background Pattern */}
          <div style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundImage: darkMode 
              ? 'radial-gradient(circle at 1px 1px, rgba(255,255,255,0.05) 1px, transparent 0)'
              : 'radial-gradient(circle at 1px 1px, rgba(0,0,0,0.02) 1px, transparent 0)',
            backgroundSize: '20px 20px',
            pointerEvents: 'none',
            zIndex: 0
          }} />
          
          {/* Content */}
          <div style={{ position: 'relative', zIndex: 1, width: '100%' }}>
            {children}
          </div>
        </main>

        {/* Scroll to top button for scrollable sections */}
        {needsScrolling && (
          <button
            onClick={() => {
              const main = document.querySelector('main')
              main.scrollTo({ top: 0, behavior: 'smooth' })
            }}
            style={{
              position: 'fixed',
              bottom: '2rem',
              right: '2rem',
              background: currentTheme.text,
              color: currentTheme.bg,
              border: 'none',
              borderRadius: '50%',
              width: '48px',
              height: '48px',
              cursor: 'pointer',
              fontSize: '1.2rem',
              boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
              transition: 'all 0.3s ease',
              zIndex: 1000,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}
            onMouseEnter={(e) => {
              e.target.style.transform = 'scale(1.1)'
            }}
            onMouseLeave={(e) => {
              e.target.style.transform = 'scale(1)'
            }}
          >
            ↑
          </button>
        )}
      </div>

      {/* CSS for animations */}
      <style jsx global>{`
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
        
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        
        /* Smooth scrolling */
        html {
          scroll-behavior: smooth;
        }
        
        /* Custom scrollbar */
        ::-webkit-scrollbar {
          width: 8px;
        }
        
        ::-webkit-scrollbar-track {
          background: ${currentTheme.bg};
        }
        
        ::-webkit-scrollbar-thumb {
          background: ${currentTheme.border};
          border-radius: 4px;
        }
        
        ::-webkit-scrollbar-thumb:hover {
          background: ${currentTheme.textSecondary};
        }
        
        /* Focus styles for accessibility */
        *:focus {
          outline: 2px solid #3b82f6;
          outline-offset: 2px;
        }
        
        /* Disable outline for mouse users */
        .js-focus-visible *:focus:not(.focus-visible) {
          outline: none;
        }
      `}</style>
    </>
  )
}

export default Layout